out, bad = [], []
for i, (name, cat, region, lat, lng, summary, story, best, tip, sources) in enumerate(S, 1):
    slug = re.sub(r"[^a-z0-9]+", "-", name.lower().replace("'", "")).strip("-")
    words = len(story.split())
    if not 80 <= words <= 150:
        bad.append(f"{name}: {words} words")
    if "—" in story or "–" in story:
        bad.append(f"{name}: dash")
    out.append({"id": f"ke-{i:02d}", "name": name, "slug": slug, "category": cat, "region": region,
                "lat": lat, "lng": lng, "summary": summary, "story": story, "bestTime": best,
                "tip": tip, "imageCredit": "", "sources": sources})
if bad:
    sys.exit("\n".join(bad))
json.dump(out, open("assets/stories/kenya.json", "w"), indent=2, ensure_ascii=False)
print(len(out), "stories;", sum(len(s["story"].split()) for s in out), "words")
